-- 九年级 U1 完形/听力 灌库(返工去重版)。先删旧 g9/U1 再灌新 6+6。volume='g9' unit='U1' grade=9。
BEGIN;

-- ===== 完形:删旧 → 灌 6 篇(每篇10空) =====
DELETE FROM public.junior_cloze WHERE volume='g9' AND unit='U1';
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, 'g9', 'U1', 'Learning from English Shows', 'Tony has found a fun way to (1)____ English: watching English TV shows. Every evening he watches one short (2)____ with subtitles. He does not just watch for fun. He listens to how the actors (3)____ the words and then copies them. When he hears a useful (4)____, he says it again and again until it sounds (5)____. Sometimes he covers the Chinese subtitles and tries to (6)____ what the actors are saying. At first it was (7)____, but slowly he could understand more. His listening and (8)____ have both got better. Now Tony can speak more (9)____ than before. He says learning English can be as fun as (10)____ a show.', 112, 3, '[{"q":"1","answer":"A","options":["learn","teach","forget","draw"],"explanation":"a way to learn 学习的方法"},{"q":"2","answer":"B","options":["song","show","game","meal"],"explanation":"a short show 一集节目"},{"q":"3","answer":"C","options":["write","count","pronounce","draw"],"explanation":"how actors pronounce 发音"},{"q":"4","answer":"D","options":["number","colour","size","expression"],"explanation":"useful expression 有用表达"},{"q":"5","answer":"A","options":["natural","terrible","silent","empty"],"explanation":"sound natural 听起来自然"},{"q":"6","answer":"B","options":["forget","guess","lose","drop"],"explanation":"guess what 猜测"},{"q":"7","answer":"C","options":["easy","free","hard","lucky"],"explanation":"at first hard 起初难"},{"q":"8","answer":"D","options":["weather","money","health","pronunciation"],"explanation":"listening and pronunciation 听力和发音"},{"q":"9","answer":"B","options":["slowly","easily","quietly","sadly"],"explanation":"speak more easily 更轻松地说"},{"q":"10","answer":"C","options":["watch","watched","watching","watches"],"explanation":"as fun as watching 和看节目一样有趣(动名词)"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, 'g9', 'U1', 'My Mistake Notebook', 'After every test, many students just look at their (1)____ and forget about them. But Linda does something (2)____. She keeps a mistake notebook. In it, she writes down every question she got (3)____. Next to it, she writes the (4)____ answer and the reason for her mistake. This helps her understand (5)____ she was wrong. Every weekend, she (6)____ her notebook and does the wrong questions (7)____. Slowly, she stops making the same mistakes. Her teacher says a mistake notebook is a very (8)____ tool. "Your mistakes can become your best (9)____," she always says. Linda''s grades have really (10)____ since she started.', 104, 3, '[{"q":"1","answer":"B","options":["friends","scores","songs","games"],"explanation":"look at scores 看分数"},{"q":"2","answer":"A","options":["different","boring","easy","late"],"explanation":"something different 不一样的事"},{"q":"3","answer":"C","options":["right","easy","wrong","new"],"explanation":"got wrong 做错的"},{"q":"4","answer":"D","options":["same","free","short","correct"],"explanation":"the correct answer 正确答案"},{"q":"5","answer":"B","options":["who","why","when","where"],"explanation":"understand why 明白为什么"},{"q":"6","answer":"A","options":["reviews","forgets","loses","sells"],"explanation":"review 复习"},{"q":"7","answer":"C","options":["never","once","again","seldom"],"explanation":"do them again 重做"},{"q":"8","answer":"D","options":["terrible","silly","empty","useful"],"explanation":"a useful tool 有用工具"},{"q":"9","answer":"A","options":["teachers","enemies","games","secrets"],"explanation":"best teachers 最好的老师"},{"q":"10","answer":"B","options":["fallen","improved","stopped","ended"],"explanation":"grades improved 成绩提高"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, 'g9', 'U1', 'Little Bits of Time', 'Peter is always busy, but he still learns many English words. His (1)____ is using little bits of time. He makes small word (2)____ and carries them in his (3)____. On the bus to school, he takes them (4)____ and reads a few. While he is (5)____ for his friends, he looks at one or two more. He even reviews them for a minute before he goes to (6)____. Each time is very (7)____, but the minutes add (8)____. In this way, Peter learns about ten new words every (9)____ without spending extra hours. He believes that time is like gold and should never be (10)____.', 106, 3, '[{"q":"1","answer":"C","options":["problem","mistake","secret","rule"],"explanation":"his secret 秘诀"},{"q":"2","answer":"D","options":["songs","games","books","cards"],"explanation":"word cards 单词卡"},{"q":"3","answer":"A","options":["pocket","head","garden","river"],"explanation":"in his pocket 口袋里"},{"q":"4","answer":"B","options":["off","out","away","down"],"explanation":"take them out 拿出来"},{"q":"5","answer":"C","options":["sleeping","running","waiting","singing"],"explanation":"waiting for 等待"},{"q":"6","answer":"D","options":["school","work","class","bed"],"explanation":"go to bed 睡觉"},{"q":"7","answer":"A","options":["short","long","hard","free"],"explanation":"very short 很短"},{"q":"8","answer":"B","options":["down","up","off","in"],"explanation":"add up 累积"},{"q":"9","answer":"D","options":["year","week","month","day"],"explanation":"every day 每天"},{"q":"10","answer":"C","options":["saved","used","wasted","kept"],"explanation":"never be wasted 不该浪费"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, 'g9', 'U1', 'Speaking in Front of Others', 'Maria used to be very (1)____. She was afraid to speak English in (2)____ of the class. Her face turned red whenever the teacher asked her a (3)____. One day, the teacher asked everyone to give a short (4)____ about their hobby. Maria was so (5)____ that she could not sleep. But she decided to (6)____ it a try. She practised her talk many times at (7)____ and read it (8)____ until she knew it well. When the big day came, she stood up and spoke (9)____. Everyone listened and clapped for her. After that, Maria was no longer afraid to (10)____ in public.', 104, 3, '[{"q":"1","answer":"D","options":["brave","tall","happy","shy"],"explanation":"used to be shy 曾很害羞"},{"q":"2","answer":"A","options":["front","back","top","middle"],"explanation":"in front of 在……前面"},{"q":"3","answer":"B","options":["song","question","game","story"],"explanation":"ask a question 提问"},{"q":"4","answer":"C","options":["song","game","talk","meal"],"explanation":"give a short talk 做简短发言"},{"q":"5","answer":"D","options":["glad","free","lucky","nervous"],"explanation":"so nervous 紧张得"},{"q":"6","answer":"A","options":["give","take","make","get"],"explanation":"give it a try 试一试"},{"q":"7","answer":"B","options":["school","home","noon","night"],"explanation":"at home 在家"},{"q":"8","answer":"C","options":["quietly","slowly","aloud","alone"],"explanation":"read aloud 朗读"},{"q":"9","answer":"A","options":["clearly","badly","loudly","slowly"],"explanation":"spoke clearly 说得清楚"},{"q":"10","answer":"D","options":["sleep","sing","run","speak"],"explanation":"speak in public 当众说"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, 'g9', 'U1', 'Asking a Classmate for Help', 'Jack was good at most subjects, but he had trouble with English (1)____. He could not understand how to use the object (2)____. His homework was often (3)____, and he felt worried. Instead of giving up, he decided to ask his (4)____ Lily for help. Lily was happy to (5)____ him. She explained the rule with simple (6)____ and made him a few practice (7)____. "Don''t worry," she said. "Everyone needs help (8)____." With her help, Jack slowly began to (9)____ the grammar. His next test was much (10)____. Jack learned that asking a classmate for help is a smart thing to do.', 103, 3, '[{"q":"1","answer":"A","options":["grammar","music","sports","art"],"explanation":"English grammar 英语语法"},{"q":"2","answer":"B","options":["song","clause","game","number"],"explanation":"object clause 宾语从句"},{"q":"3","answer":"C","options":["right","easy","wrong","free"],"explanation":"often wrong 常做错"},{"q":"4","answer":"D","options":["teacher","brother","neighbour","classmate"],"explanation":"ask his classmate 问同学"},{"q":"5","answer":"A","options":["help","stop","watch","leave"],"explanation":"happy to help 乐意帮"},{"q":"6","answer":"B","options":["colours","examples","songs","games"],"explanation":"with examples 用例子"},{"q":"7","answer":"C","options":["pictures","meals","questions","trips"],"explanation":"practice questions 练习题"},{"q":"8","answer":"D","options":["never","seldom","hardly","sometimes"],"explanation":"needs help sometimes 有时需要帮助"},{"q":"9","answer":"B","options":["forget","understand","lose","drop"],"explanation":"understand the grammar 理解语法"},{"q":"10","answer":"A","options":["better","worse","harder","smaller"],"explanation":"much better 好多了"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, 'g9', 'U1', 'Making a Study Plan', 'Exams were coming, and Emma had a lot to (1)____. At first she felt worried because there was so much to do. Then she decided to make a study (2)____. She wrote down all the subjects and how much (3)____ she needed for each one. She put the most difficult subject (4)____. Every day, she studied for a short (5)____ and then took a break. She did not try to learn everything in one (6)____. Before bed, she quickly (7)____ what she had studied that day. Because of her plan, Emma felt (8)____ and ready. She did not need to (9)____ all night before the exam. A good plan, she found, makes study easier and (10)____.', 116, 3, '[{"q":"1","answer":"A","options":["review","sing","draw","buy"],"explanation":"a lot to review 很多要复习"},{"q":"2","answer":"B","options":["game","plan","song","rule"],"explanation":"a study plan 学习计划"},{"q":"3","answer":"C","options":["money","food","time","water"],"explanation":"how much time 多少时间"},{"q":"4","answer":"D","options":["last","late","slow","first"],"explanation":"the hardest first 最难的先做"},{"q":"5","answer":"A","options":["while","year","week","month"],"explanation":"a short while 一小会儿"},{"q":"6","answer":"B","options":["day","night","week","hour"],"explanation":"in one night 一晚之内"},{"q":"7","answer":"C","options":["lost","dropped","checked","sold"],"explanation":"checked what 检查所学"},{"q":"8","answer":"D","options":["angry","sad","tired","calm"],"explanation":"felt calm 感到平静"},{"q":"9","answer":"A","options":["study","sleep","eat","play"],"explanation":"study all night 通宵学"},{"q":"10","answer":"B","options":["worse","better","harder","slower"],"explanation":"easier and better 更轻松更好"}]'::jsonb, 6);

-- ===== 听力:删旧 → 灌 6 篇(每篇5题) =====
DELETE FROM public.junior_listening_exercises WHERE volume='g9' AND unit='U1';
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U1 听力·对话 How to Practise Listening', '九上 Unit1 听力·学习方法', 2, 'Anna: Ben, my listening is really weak. How can I practise it?
Ben: I listen to short English songs and stories every day.
Anna: Do you understand everything?
Ben: No, not at first. But I listen to the same one a few times.
Anna: That''s a good idea. Anything else?
Ben: Yes. I try to catch the key words, not every word.
Anna: So I don''t need to understand every word?
Ben: Right. Just relax and listen a little every day. You''ll get better.', 'Anna说听力弱,问Ben怎么练。Ben:每天听英文歌和故事,起初听不懂就同一段多听几遍,只抓关键词而非每个词,放松、每天听一点就会进步。', 'us_female', '[{"q":"What is Anna''s problem?","type":"choice","answer":"A","options":["Her listening is weak.","Her reading is weak.","Her writing is weak.","Her speaking is weak."]},{"q":"How does Ben practise listening?","type":"choice","answer":"B","options":["By reading books.","By listening to songs and stories every day.","By writing diaries.","By playing games."]},{"q":"Does Ben understand everything at first?","type":"choice","answer":"C","options":["Yes, all of it.","Yes, most of it.","No.","He never listens."]},{"q":"What does Ben try to catch?","type":"choice","answer":"D","options":["Every word.","The Chinese.","The music only.","The key words."]},{"q":"What is Ben''s advice?","type":"choice","answer":"A","options":["Relax and listen a little every day.","Stop listening.","Listen only before exams.","Translate every word."]}]'::jsonb, '[]'::jsonb, 'long', 'g9', 'U1');
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U1 听力·短文 Listening While Running', '九上 Unit1 听力·学习方法', 2, 'Every morning, I go running in the park. But I don''t just run. I also learn English. I put on my earphones and listen to short English news on my phone. At first, the news was too fast, and I could not follow it. But I did not stop. I listened to the same news again later and read the words. Now I can understand most of it. Running and listening together save me time, and they make my morning happy.', '“我”每天清晨在公园跑步,同时戴耳机听手机里的英文短新闻。起初语速太快跟不上,但没放弃,事后又听同一条并读文字,现在大部分能懂。边跑边听省时,清晨更愉快。', 'us_male', '[{"q":"Where does the speaker run?","type":"choice","answer":"B","options":["At school.","In the park.","On the playground.","At home."]},{"q":"What does the speaker listen to?","type":"choice","answer":"C","options":["English songs.","Chinese stories.","Short English news.","Pop music."]},{"q":"What was the problem at first?","type":"choice","answer":"D","options":["The phone was broken.","The park was noisy.","The words were Chinese.","The news was too fast."]},{"q":"What did the speaker do to understand better?","type":"choice","answer":"A","options":["Listened again and read the words.","Gave up.","Asked a friend.","Ran faster."]},{"q":"Why does the speaker like this way?","type":"choice","answer":"B","options":["It is expensive.","It saves time.","It is boring.","It wastes time."]}]'::jsonb, '[]'::jsonb, 'short', 'g9', 'U1');
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U1 听力·对话 Guessing Words While Reading', '九上 Unit1 听力·学习方法', 2, 'Tom: Lily, you read English so fast. What''s your secret?
Lily: When I meet a new word, I don''t stop to look it up.
Tom: Really? But how do you know the meaning?
Lily: I guess it from the other words in the sentence.
Tom: Doesn''t that slow you down?
Lily: No. Stopping for every word slows you down more.
Tom: So I should just keep reading?
Lily: Yes. You can check important words later. Guessing helps you read faster.', 'Tom问Lily读得快的秘诀。Lily:遇生词不停下查词典,而是根据句中其他词猜义;每个词都停反而更慢;重要的词可稍后再查,猜词帮助读得更快。', 'us_female', '[{"q":"What is Lily good at?","type":"choice","answer":"C","options":["Writing stories.","Singing songs.","Reading English fast.","Drawing pictures."]},{"q":"What does Lily do when she meets a new word?","type":"choice","answer":"D","options":["She stops at once.","She skips the page.","She asks Tom.","She doesn''t stop to look it up."]},{"q":"How does Lily know the meaning?","type":"choice","answer":"A","options":["She guesses from the sentence.","She uses a phone.","She asks the teacher.","She reads Chinese."]},{"q":"What slows readers down more?","type":"choice","answer":"B","options":["Reading in groups.","Stopping for every word.","Guessing words.","Reading aloud."]},{"q":"When can Tom check important words?","type":"choice","answer":"C","options":["Never.","Before reading.","Later.","In a song."]}]'::jsonb, '[]'::jsonb, 'long', 'g9', 'U1');
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U1 听力·短文 Using a Learner''s Dictionary', '九上 Unit1 听力·学习方法', 2, 'When I learn a new word, I like to use a learner''s dictionary. It is different from a normal dictionary. It uses simple English to explain each word, so I can understand the meaning easily. It also gives example sentences, which show me how to use the word. Sometimes one word has several meanings, and the dictionary shows them all. After I read the example, I make my own sentence with the word. A good dictionary is like a quiet teacher that is always ready to help.', '学新词时,“我”爱用学习型词典。它和普通词典不同:用简单英语解释,容易懂;还给例句示范用法;一词多义时全列出。读完例句后我用该词自己造句。好词典像一位随时帮忙的安静老师。', 'us_male', '[{"q":"What does the speaker use to learn a new word?","type":"choice","answer":"D","options":["A phone game.","A storybook.","A song list.","A learner''s dictionary."]},{"q":"How is it different from a normal dictionary?","type":"choice","answer":"A","options":["It uses simple English to explain.","It uses pictures only.","It has no words.","It is in Chinese."]},{"q":"What else does the dictionary give?","type":"choice","answer":"B","options":["Free gifts.","Example sentences.","Music.","Games."]},{"q":"What does the speaker do after reading the example?","type":"choice","answer":"C","options":["Closes the book.","Forgets the word.","Makes his own sentence.","Draws a picture."]},{"q":"What is a good dictionary compared to?","type":"choice","answer":"D","options":["A loud radio.","A fast train.","A big game.","A quiet teacher."]}]'::jsonb, '[]'::jsonb, 'short', 'g9', 'U1');
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U1 听力·对话 Starting a Study Group', '九上 Unit1 听力·学习方法', 2, 'Lucy: Shall we start an English study group?
Mark: Good idea! How many people should we have?
Lucy: About four. Too many people will be noisy.
Mark: OK. When and where shall we meet?
Lucy: Every Sunday afternoon at my home.
Mark: What will we do in the group?
Lucy: We can read together, share word cards and test each other.
Mark: Great! Studying with friends is more fun than studying alone.', 'Lucy提议办英语学习小组。两人商定:约四人(太多会吵);每周日下午在Lucy家;活动是一起读、分享单词卡、互相测验。Mark觉得和朋友一起学比一个人学更有趣。', 'us_female', '[{"q":"What do they want to start?","type":"choice","answer":"A","options":["An English study group.","A sports team.","A music band.","A book shop."]},{"q":"How many people does Lucy want?","type":"choice","answer":"B","options":["About ten.","About four.","About twenty.","Only two."]},{"q":"Why not too many people?","type":"choice","answer":"C","options":["It will be cheap.","It will be boring.","It will be noisy.","It will be easy."]},{"q":"When will they meet?","type":"choice","answer":"D","options":["Every morning.","On Monday night.","Every day.","Every Sunday afternoon."]},{"q":"What does Mark think about studying with friends?","type":"choice","answer":"A","options":["It is more fun than studying alone.","It is harder.","It is boring.","It wastes time."]}]'::jsonb, '[]'::jsonb, 'long', 'g9', 'U1');
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U1 听力·短文 Getting Ready Before Class', '九上 Unit1 听力·学习方法', 2, 'Many students only study after class, but I also get ready before class. The night before, I read the new lesson in my textbook. I look at the new words and mark the parts I don''t understand. Then, in class, I listen more carefully to those difficult parts. Because I am ready, I can follow the teacher easily and answer more questions. Getting ready before class only takes ten minutes, but it makes the lesson much easier. I think it is one of the best study habits.', '许多同学只在课后学,而“我”也在课前预习:前一晚读课本新课,看生词、标出不懂的地方;上课时更专心听那些难点。因为有准备,能轻松跟上老师、多回答问题。预习每次只花十分钟,却让课变得简单,是最好的学习习惯之一。', 'us_female', '[{"q":"What does the speaker do that many students don''t?","type":"choice","answer":"B","options":["Sleep in class.","Get ready before class.","Skip homework.","Eat in class."]},{"q":"When does the speaker read the new lesson?","type":"choice","answer":"D","options":["After the exam.","During the holiday.","In the morning only.","The night before."]},{"q":"What does the speaker mark?","type":"choice","answer":"C","options":["The easy parts.","The pictures.","The parts he doesn''t understand.","The page numbers."]},{"q":"What is the result in class?","type":"choice","answer":"A","options":["He can follow the teacher easily.","He feels sleepy.","He is always late.","He cannot hear."]},{"q":"How long does getting ready take?","type":"choice","answer":"B","options":["Two hours.","Ten minutes.","A whole day.","One minute."]}]'::jsonb, '[]'::jsonb, 'short', 'g9', 'U1');

COMMIT;

-- count 校验(预期 完形6 / 听力6)
SELECT 'cloze' k, count(*) v, 6 expect FROM public.junior_cloze WHERE volume='g9' AND unit='U1'
UNION ALL SELECT 'listening', count(*), 6 FROM public.junior_listening_exercises WHERE volume='g9' AND unit='U1';
